        m.W[0] = x - 10; m.W[1] = y - 10; m.W[2] = x + 10; m.W[3] = y + 10
        // v() L85 -> a(k.ac, Y): real context-bounds quad against camRect
        m.Y[0] = m.W[0]; m.Y[1] = m.W[1]; m.Y[2] = m.W[2]; m.Y[3] = m.W[3]
        m.Z[0] = z0; m.Z[3] = 300; m.Z[4] = 1
        w.npcs.add(0, m)
        return m
    }

