                       start = 936, end = 937)
        assertEquals(938, e.Z[0], "Z[0] = script-entity uid")
        assertEquals(7519, e.Z[6], "Z[6] = home ak")
        assertEquals(339, e.Z[1], "Z[1] = cable y")
        assertEquals(0, e.Z[2]); assertEquals(0, e.Z[3])
        assertEquals(936, e.Z[4]); assertEquals(937, e.Z[5])
        assertTrue(e.P and 16 != 0, "P|=16")
        assertEquals(3, e.az)
        assertEquals(0, e.S)
    }

    @Test fun `ax40 resolves anchor endpoints once`() {
        val w = world(); w.npcs.clear()
        val e = gondolaRun(w)
        w.npcFsm.tickAx40(e, w, w.player)
        assertEquals(7480, e.Z[2], "Z[2] = start anchor ak")
        assertEquals(7947, e.Z[3], "Z[3] = end anchor ak")
        assertEquals(-1, e.Z[4]); assertEquals(-1, e.Z[5])
        val anchor = w.npcs.first { it.aw == 936 }
        assertTrue(e.s === anchor, "s = start anchor entity")
    }

    /**
     * Board the gondola the way a real frame does: the first overlap tick
     * binds `aS.ac` then L88 unbinds it again — `aS.t()` refreshed `W` at
     * the pre-hop position, so the stale box misses the gondola by 1px
     * (faithful — i.java L53→L88). The player's per-frame `t()` (called
     * by `collideSides` inside `w.tick`) then raises the box to the hang
     * point and the next npc tick re-binds, this time overlapping.
     */
    private fun board(w: Level0World, e: Entity) {
        val p = w.player
        w.npcFsm.tickAx40(e, w, p)                       // anchor resolve
        p.setPositionPx(e.ak, e.al); p.refreshBoxes()
        w.npcFsm.tickAx40(e, w, p)                       // bind + transient unbind
        p.refreshBoxes()                                 // player's frame t()
        w.npcFsm.tickAx40(e, w, p)                       // re-bind, holds
    }

    @Test fun `ax40 overlap binds the player into anim 164`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = gondolaRun(w)
        board(w, e)
        assertTrue(p.ac === e, "k.aS.ac = gondola")
        assertEquals(164, p.S, "player -> i(164) ride anim")
        assertEquals(e.ak, p.ak, "player pinned to gondola x")
        assertEquals(e.al + 25 + (p.W[3] - p.W[1]), p.al, "hang offset")
    }

    @Test fun `ax40 bind unbinds once then re-binds`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = gondolaRun(w)
        w.npcFsm.tickAx40(e, w, p)
        p.setPositionPx(e.ak, e.al); p.refreshBoxes()
        w.npcFsm.tickAx40(e, w, p)                       // L53 bind → L88 unlink
        assertNull(p.ac, "L88 unlink on the stale box (i.java:17239)")
        assertEquals(164, p.S, "i(164) already set by the bind")
        p.refreshBoxes()                                 // frame t() raises W
        w.npcFsm.tickAx40(e, w, p)
        assertTrue(p.ac === e, "re-bind holds once W reaches the gondola")
    }

    @Test fun `ax40 ride arm sags the cable catenary`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = gondolaRun(w)
        board(w, e)
        w.npcFsm.tickAx40(e, w, p)                  // ride tick
        // the bound script's key-35 op25 arm slides the gondola +12px
        // at step 1 (ak 7519→7531 — script-driven travel, i.aa());
        // r04=182, r05=233 → al=339+2
        assertEquals(7531, e.ak, "op25 arm moves the gondola +12px")
        assertEquals(341, e.al, "catenary sag near the start anchor")
        assertFalse(p.av, "faces the travel direction (Z2<Z3)")
        assertEquals(e.ak, p.ak)
    }

    @Test fun `ax40 context tap dismounts and kicks the fall`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = gondolaRun(w)
        board(w, e)
        w.pad.commit(16388)
        w.npcFsm.tickAx40(e, w, p)
        assertNull(p.ac, "aS.a(null) unlink")
        assertEquals(157, p.S, "player -> i(157) hop-off anim")
        assertEquals(2048, p.ag, "hop away +x (av=false)")
        assertEquals(-2560, p.ah)
        assertEquals(512, e.ah, "gondola departs")
        assertEquals(1536, e.aj)
        assertEquals(-1, e.ca)
    }

    @Test fun `ax40 S1 resets to the start anchor`() {
        val w = world(); w.npcs.clear()
        val e = ax40At(w, 935, 7519, 339, 1)
        e.ak = 9999; e.ah = 100
        var guard = 0
        while (e.S == 1 && guard++ < 100) {
            e.advanceAnim()
            w.npcFsm.tickAx40(e, w, w.player)
        }
        assertEquals(0, e.S)
        assertEquals(7519, e.ak, "respawned at Z[6]")
        assertEquals(339, e.al, "respawned at Z[1]")
        assertEquals(-1, e.claimLatchX)
        assertNull(e.scriptOps)
        assertEquals(0, e.cK)
    }

    @Test fun `ax40 past the far endpoint kicks the departure fall`() {
        val w = world(); w.npcs.clear()
        val e = gondolaRun(w)
        w.npcFsm.tickAx40(e, w, w.player)
        e.ak = e.Z[3] + 1                            // past 7947
        w.npcFsm.tickAx40(e, w, w.player)
        assertEquals(512, e.ah, "L81 departure kick")
        assertEquals(-1, e.ca)
    }

    @Test fun `ax40 falling gondola crushes ax11s`() {
        val w = world(); w.npcs.clear()
        val e = gondolaRun(w)
        w.npcFsm.tickAx40(e, w, w.player)
        e.ah = 3000                                  // already falling
        val s = Entity(11, w.clips[7])
        s.setAnim(3); s.setPositionPx(e.ak, e.al); s.refreshBoxes()
        w.npcs.add(s)
        w.npcFsm.tickAx40(e, w, w.player)
        assertEquals(0, s.S, "d(bd) → i(0) death chain")
        assertEquals(1, e.S, "gondola -> reset arm")
    }

    @Test fun `ax40 unlinks a player who walked off`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = gondolaRun(w)
        w.npcFsm.tickAx40(e, w, w.player)
        p.ac = e
        p.setPositionPx(e.ak + 400, e.al); p.refreshBoxes()
        w.npcFsm.tickAx40(e, w, w.player)
        assertNull(p.ac, "L88 walked-off unlink")
    }
}

// ---- slice 43a — script tables `by`/`bz`/`eH` (k.java:6196-6320) -------
class ScriptTablesTest {

    private fun tables() = ScriptTables.load(
        java.io.File("../generated/level0/scripts.bin").readBytes())

    @Test fun `loader consumes the whole entry`() {
        val t = tables()
        assertEquals(13, t.eH.size, "pack-6 entry-007 carries 13 scripts")
    }

    @Test fun `eH carries the level-0 script uids`() {
        val t = tables()
        assertEquals(938, t.eH[11], "gondola script uid 938 at index 11")
        assertEquals(listOf(116, 47, 250, 300, 313, 532, 105, 104, 927,
            579, 327, 938, 52), t.eH.toList())
    }

    @Test fun `s resolves script uid to index or -1`() {
        val t = tables()
        assertEquals(11, t.s(938))
        assertEquals(0, t.s(116))
        assertEquals(-1, t.s(9999))
    }

    @Test fun `t returns eI op payload lengths`() {
        val t = tables()
        assertEquals(6, t.t(100)); assertEquals(2, t.t(101))
        assertEquals(9, t.t(106)); assertEquals(8, t.t(109))
        assertEquals(4, t.t(114))
    }

    @Test fun `bz seeds the PC on the first step-group`() {
        val t = tables()
        for (s in t.by.indices) for (b in t.by[s].indices) {
            val blk = t.by[s][b]
            val type = blk[0].toInt() and 0xFF
            val expect = if (type == 2 || type == 3) 6 else 4
            assertEquals(expect, t.bz[s][b],
                "script $s block $b type $type header")
            // The offset must land on a group key — before the size tail.
            assertTrue(t.bz[s][b] < blk.size - 2,
                "script $s block $b: PC inside content")
        }
    }

    @Test fun `script 938 blocks parse to plausible ops`() {
        val t = tables()
        val by = t.by[11]
        assertTrue(by.isNotEmpty(), "gondola script has blocks")
        // Every op byte in every block must be a known opcode shape —
        // re-walk the groups to prove the layout parses cleanly.
        for (blk in by) {
            var pc = t.bz[11][t.by[11].indexOf(blk)]
            val groups = (blk[pc - 2].toInt() and 0xFF) or
                ((blk[pc - 1].toInt() and 0xFF) shl 8)
            var seen = 0
            while (pc < blk.size - 2 && seen < groups) {
                pc += 3                            // key16 + count8
                val nops = blk[pc - 1].toInt() and 0xFF
                for (o in 0 until nops) {
                    val op = blk[pc].toInt() and 0xFF
                    pc += 1 + if (op >= 100) ScriptTables.EI[op - 100]
                              else when (op) {
                                  11, 12, 21, 25, 31, 41 -> 4
                                  13 -> 5
                                  22, 32, 42 -> 2
                                  23, 24, 43, 44 -> 4
                                  34, 35, 36 -> 2 + 2 * ((op - 34) % 3 + 1)
                                  37, 38, 39 -> 2 * ((op - 34) % 3 + 1)
                                  else -> 0
                              }
                }
                seen++
            }
            assertEquals(blk.size - 2, pc, "block content ends at the tail")
        }
    }

    @Test fun `world exposes the tables through LevelCellSource`() {
        val w = world()
        assertEquals(13, w.kEh.size)
        assertEquals(938, w.kEh[11])
        assertEquals(11, w.kSIndex(938))
        assertEquals(-1, w.kSIndex(9999))
        assertNotNull(w.claimOps(11), "claimOps → kBz[11] group offsets")
        assertNull(w.claimOps(99))
        assertEquals(6, w.kT(100))
    }

    @Test fun `bindScript latches cd7 only on first alloc`() {
        val w = world()
        val e = Entity(11, w.clips[7])
        e.setPositionPx(100, 100)
        w.npcs.add(e)
        e.bindScript(11, w)
        assertEquals(11, e.ca)
        assertTrue(e.cd[7])
        assertNotNull(e.scriptOps, "reloadScriptOps seeds cL from kBz")
        // a second bind (post-release) must NOT re-set cd[7] semantics —
        // the original's `cd == null` alloc check fires exactly once.
        e.cd[7] = false
        e.claimLatchX = -1                     // simulate bI() release
        e.bindScript(5, w)
        assertFalse(e.cd[7], "cd[7] writes only on the first alloc")
        assertEquals(5, e.ca)
    }
}

// =====================================================================
// Slice 43b — i.aa() claim-script interpreter (the k.by VM).
// =====================================================================

private fun u16le(v: Int) =
    byteArrayOf((v and 0xFF).toByte(), ((v shr 8) and 0xFF).toByte())

/** `[key u16][cnt u8][ops]` — one script step-group. */
private fun scriptGroup(key: Int, vararg ops: ByteArray): ByteArray {
    val g = ByteArray(3 + ops.sumOf { it.size })
    var p = 0
    u16le(key).copyInto(g, p); p += 2
    g[p++] = ops.size.toByte()
    for (o in ops) { o.copyInto(g, p); p += o.size }
    return g
}

/** Raw block: `[type][pad][uid iff 2/3][gcnt u16]` + groups + `u16(hdr)`. */
private fun scriptBlock(type: Int, uid: Int, vararg groups: ByteArray): ByteArray {
    val hdr = if (type == 2 || type == 3) 6 else 4
    val b = ByteArray(hdr + groups.sumOf { it.size } + 2)
    var p = 0
    b[p++] = type.toByte(); b[p++] = 0
    if (type == 2 || type == 3) { u16le(uid).copyInto(b, p); p += 2 }
    u16le(groups.size).copyInto(b, p); p += 2
    for (g in groups) { g.copyInto(b, p); p += g.size }
    u16le(hdr).copyInto(b, p)
    return b
}

private fun opMove(x: Int, y: Int) = byteArrayOf(21) + u16le(x) + u16le(y)
private fun opAnim(a: Int) = byteArrayOf(22) + u16le(a)
private fun opSub1(sub: Int) = byteArrayOf(37) + u16le(sub)
private fun opSub2(sub: Int, r2: Int) = byteArrayOf(38) + u16le(sub) + u16le(r2)

/** World carrying a synthetic one-script table (`eH=[7]`, ca=0). */
private fun scriptedWorld(vararg blocks: ByteArray): Level0World {
    val base = world()
    val tables = ScriptTables(
        eH = intArrayOf(7),
        by = arrayOf(arrayOf(*blocks)),
        bz = arrayOf(IntArray(blocks.size) { i ->
            val t = blocks[i][0].toInt() and 0xFF
            if (t == 2 || t == 3) 6 else 4
        }),
    )
    return Level0World(base.level, base.clips, DeterministicRandom(1L),
        scripts = tables).also { it.npcs.clear() }   // uid-space is the test's
}

/** ax5 claimer bound to script index 0 and stepping (`scriptStep=0`). */
private fun claimer(w: Level0World): Entity {
    val e = Entity(5, null)
    e.aw = 700
    w.npcs.add(e)
    e.bindScript(0, w)
    e.scriptKeyStep(0, w)
    return e
}

class Slice43bTest {


    @Test fun `op21 lerps the target once per step until the key`() {
        val w = scriptedWorld(
            scriptBlock(2, 900, scriptGroup(10, opMove(300, 200))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900; setPositionPx(100, 100) }
        w.npcs.add(t)
        e.runClaimScript(w)                    // r02=0: arm r20=10
        assertEquals(118, t.ak, "delta=(300-100)/(10-0+1)=18")
        assertEquals(109, t.al, "delta=(200-100)/11=9")
        // key10 not consumed while step < 10
        repeat(9) { e.runClaimScript(w) }      // r02=1..9
        assertTrue(e.scriptStep > 0, "group still open mid-lerp")
        e.runClaimScript(w)                    // r02=10: consume + release
        assertEquals(300, t.ak); assertEquals(200, t.al)
        assertEquals(-2, e.scriptStep, "all-done → releaseClaim cK=-2")
    }

    @Test fun `group key ahead of the step is decoded but not consumed`() {
        val w = scriptedWorld(scriptBlock(2, 900,
            scriptGroup(0, opAnim(7)), scriptGroup(50, opAnim(9))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900; setPositionPx(0, 0) }
        w.npcs.add(t)
        e.runClaimScript(w)                    // r02=0: group0 fires + consumed
        assertEquals(7, t.S)
        e.runClaimScript(w)                    // r02=1: key50 group decodes…
        assertEquals(7, t.S, "…but its op22 does not fire (key<=step gate)")
        val pc = e.scriptOps!![0]
        assertTrue(pc > 6, "PC advanced past group0 to the key50 group")
        repeat(48) { e.runClaimScript(w) }     // r02=2..49: still gated
        assertEquals(7, t.S)
        e.runClaimScript(w)                    // r02=50: fires + consumed
        assertEquals(9, t.S)
    }

    @Test fun `op22 ax11 anim-139 bumps the kill stat and plays the anim`() {
        val w = scriptedWorld(scriptBlock(2, 900,
            scriptGroup(0, opAnim(139))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900; setPositionPx(0, 0) }
        w.npcs.add(t)
        val a0 = w.kAp[0]; val a3 = w.kAp[3]
        e.runClaimScript(w)
        assertEquals(139, t.S)
        assertEquals(a0 + 1, w.kAp[0], "k.e(0,aw>0) → ap[0]++")
        assertEquals(a3 + 1, w.kAp[3], "k.o(3) → ap[3]++")
    }

    @Test fun `op13 focuses kAe on the indexed type-2 block uid`() {
        // blk0 type1 holds op13 → blk index 1; blk1 type2 uid=936.
        // blk1's group sits at key50 so the claim stays open — otherwise
        // releaseClaim's ax5 arm rewrites k.ae back to the player.
        val w = scriptedWorld(
            scriptBlock(1, 0, scriptGroup(0, byteArrayOf(13, 1, 0, 0, 0, 0))),
            scriptBlock(2, 936, scriptGroup(50, opAnim(50))))
        val e = claimer(w)
        val t = Entity(23, null).apply { aw = 936; setPositionPx(10, 10) }
        w.npcs.add(t)
        w.kZ = true; w.kAa = false
        e.runClaimScript(w)
        assertTrue(w.kAe === t, "k.ae = k.q(block1.uid)")
        assertFalse(w.kZ); assertTrue(w.kAa, "k.Z=false, k.aa=true")
    }

    @Test fun `arg-op 37 sub-switch arms cd2 and toggles iZ`() {
        // key50 tail keeps the claim open — bI() clears cd[2] on release.
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0,
                opSub1(0),                         // cd[2]=true
                opSub1(25),                        // i.z=true
                opSub1(24)),                       // i.z=false
            scriptGroup(50, opSub1(13))))          // pending: iCe=true later
        val e = claimer(w)
        e.runClaimScript(w)
        assertTrue(e.cd[2])
        assertFalse(w.iZ, "24 clears i.z after 25 set it")
        repeat(49) { e.runClaimScript(w) }
        e.runClaimScript(w)                        // r02=50: tail fires
        assertTrue(w.iCe)
    }

    @Test fun `arg-op 38 sub-switch writes iBQ iBD and player P`() {
        val w = scriptedWorld(scriptBlock(0, 0, scriptGroup(0,
            opSub2(6, 77),                         // i.bQ = 77
            opSub2(4, 1),                          // i.bD = true
            opSub2(0, 0x40))))                     // aS.P |= 0x40
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(77, w.iBQ)
        assertTrue(w.iBD)
        assertTrue(w.player.P and 0x40 != 0)
    }

    @Test fun `arg-op 34 fires only when the lead uid is absent`() {
        // [34][uid][sub]: uid present → skip entirely; absent → fire.
        val w = scriptedWorld(scriptBlock(0, 0, scriptGroup(0,
            byteArrayOf(34) + u16le(901) + u16le(14),   // absent → iCe=false
            byteArrayOf(34) + u16le(900) + u16le(13)))) // present → would set iCe
        val e = claimer(w)
        w.npcs.add(Entity(11, null).apply { aw = 900 })
        e.runClaimScript(w)
        assertFalse(w.iCe, "uid-900 op34 must NOT fire (entity exists)")
    }

    @Test fun `L341 tail zeros player velocity while the claim steps`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(50, opSub1(0))))
        val e = claimer(w)
        w.kC = e                                     // k.C == this
        w.player.ag = 100; w.player.ah = -2560
        w.player.ai = 1; w.player.aj = 2
        e.runClaimScript(w)                          // scriptStep → 1 > 0
        assertEquals(0, w.player.ag); assertEquals(0, w.player.ah)
        assertEquals(0, w.player.ai); assertEquals(0, w.player.aj)
    }

    @Test fun `cd0 early-returns and skip-input latches cd1 + sfx23`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, opSub1(0))))
        val e = claimer(w)
        e.cd[0] = true
        e.runClaimScript(w)
        assertFalse(e.cd[2], "cd[0] → the VM does not run")
        e.cd[0] = false; e.cd[2] = true
        w.pad.commit(0x20000)                          // k.v(131072) edge
        e.runClaimScript(w)
        assertTrue(e.cd[1], "skip latch arms fast-forward")
        assertTrue(23 in w.sfxLog, "k.A(23) sfx on skip")
    }

    @Test fun `self-targeting op25 on a claimPositionType block-0`() {
        // ax11 claims: block-0 type-2 + r13==0 → r14 = the claimer, and
        // the op25 latch adds cM/cN (bind-time position) to the target.
        val w = scriptedWorld(scriptBlock(2, 900,
            scriptGroup(0, byteArrayOf(25) + u16le(30) + u16le(40))))
        val e = Entity(11, null).apply { aw = 700; setPositionPx(100, 50) }
        w.npcs.add(e)
        e.bindScript(0, w)
        e.scriptKeyStep(0, w)
        e.runClaimScript(w)
        // r18 = 30+cM(100)=130, r19 = 40+cN(50)=90; r20=0 → instant move
        assertEquals(130, e.ak); assertEquals(90, e.al)
    }
}

// ---------------------------------------------------------------------------
// slice 46 — ax6 `an()` trigger marker + ax19 `aO()` meter pickup
// ---------------------------------------------------------------------------
class Slice46Test {

    private fun axAt(w: Level0World, ax: Int, x: Int, y: Int, s: Int): Entity {
        val e = Entity(ax, w.clips[if (ax == 6) 4 else 11])
        e.setPositionPx(x, y)
        val f = mutableListOf(ax, 0, x, y, 0, s, 0)
        for (i in 7..15) f += 0
        if (ax == 6) w.npcFsm.initAx6(e, f) else w.npcFsm.initAx19(e, f)
        w.npcs.add(e)
        return e
    }

    @Test fun `ax6 armed marker fires on player overlap then removes`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 6, p.ak, p.al, 5)                       // S5 armed
        p.refreshBoxes(); e.refreshBoxes()
        w.npcFsm.tickAx6(e, w, p)
        assertEquals(6, e.S, "S5 + overlap → i(6)")
        // wind down: anim end → k.c(this) removal
        e.T = w.clips[4]!!.frameCount(e.S) - 1
        e.U = w.clips[4]!!.frameDuration(e.S, e.T) - 1
        w.npcFsm.tickAx6(e, w, p)
        assertTrue(e in w.pendingRemove, "S6 r() → k.c(this)")
    }

    @Test fun `ax6 armed S3 stays armed without overlap`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 6, p.ak + 4000, p.al + 4000, 3)         // far away
        w.npcFsm.tickAx6(e, w, p)
        assertEquals(3, e.S, "no overlap → still armed")
        // clip4 anim3's object carries ZERO rects → degenerate W → the
        // i.a() point-box reject keeps S3 dormant even under the player
        // (faithful: the same arm is dead in the original too).
        e.setPositionPx(p.ak, p.al); e.refreshBoxes(); p.refreshBoxes()
        w.npcFsm.tickAx6(e, w, p)
        assertEquals(3, e.S, "S3 + degenerate W → i.a() reject")
    }

    @Test fun `ax19 pickup overlap fires i(18) + sfx17 + 5 sparks`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 19, p.ak, p.al, 17)                     // S17 idle
        p.setAnim(0)                                           // g.c(0) ok
        p.refreshBoxes(); e.refreshBoxes()
        w.npcFsm.tickAx19(e, w, p)
        assertEquals(18, e.S, "overlap → i(18)")
        assertTrue(17 in w.sfxLog, "k.A(17) sfx")
        assertEquals(5, w.pendingInsert.size, "5x a(74,54,5,300) sparks")
        assertTrue(e.b, "b=true latched")
        assertTrue(w.pendingInsert.all { it.ax == 74 && it.P == 528 })
    }

    @Test fun `ax19 consume restores x1 from kAx then removes`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 19, p.ak, p.al, 18)                     // consuming
        p.x1 = 40; w.kAx = 75
        e.T = w.clips[11]!!.frameCount(e.S) - 1
        e.U = w.clips[11]!!.frameDuration(e.S, e.T) - 1
        w.npcFsm.tickAx19(e, w, p)
        assertEquals(75, p.x1, "g.e(k.ax) → x1=kAx")
        assertTrue(e in w.pendingRemove)
        // dead player: no restore
        val e2 = axAt(w, 19, p.ak, p.al, 18)
        p.x1 = 0
        e2.T = w.clips[11]!!.frameCount(e2.S) - 1
        e2.U = w.clips[11]!!.frameDuration(e2.S, e2.T) - 1
        w.npcFsm.tickAx19(e2, w, p)
        assertEquals(0, p.x1, "g.g() dead → no restore")
    }

    @Test fun `ax19 spark burst table + velocity`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 19, p.ak, p.al, 17)
        p.setAnim(0); p.refreshBoxes(); e.refreshBoxes()
        w.npcFsm.tickAx19(e, w, p)
        val s = w.pendingInsert[0]
        assertTrue(s.clip === w.clips[54], "bi[74]=54 clip map")
        assertEquals(5, s.S); assertEquals(300, s.az)
        assertTrue(s.ag in (-1536..1536) && s.ag and 255 == 0,
                   "ag = j.a(-6,6)<<8")
        assertEquals(0, s.Z[6]); assertTrue(s.Z[7] in 10..15,
                   "Z[7]=j.a(10,16) lifetime")
    }

    @Test fun `ax19 gated on interact-eligible player states`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = axAt(w, 19, p.ak, p.al, 17)
        p.setAnim(67)                                          // mid-attack —
        p.refreshBoxes(); e.refreshBoxes()                     // NOT g.c()
        w.npcFsm.tickAx19(e, w, p)
        assertEquals(17, e.S, "non-g.c state → no pickup")
    }
}

// ===========================================================================
// Slice 47 — ax42 `bz()` fuse/timer zone + k.F claim slot
// ===========================================================================
class Slice47Test {

    private fun ax42At(w: Level0World, x: Int, y: Int, kind: Int, uid: Int, secs: Int): Entity {
        val e = Entity(42, null)
        e.setPositionPx(x, y)
        val f = mutableListOf(42, 0, x, y, kind, 0, 0, 0, 0, 20, 20, uid, secs)
        w.npcFsm.initAx42(e, f)
        w.npcs.add(e)
        return e
    }

    @Test fun `ax42 dormant records still claim kF + P bits every tick`() {
        val w = world(); w.npcs.clear()
        val e = ax42At(w, 0, 0, 0, 0, 30)
        assertEquals(-1, e.S, "no i() reaches ax42 in the ctor — S stays -1")
        w.kAJ = 0; w.kAM = 0
        w.npcFsm.tickAx42(e, w, w.player)
        assertSame(e, w.kF, "k.F = this")
        assertTrue(e.P and 16 != 0 && e.P and 512 != 0, "P|=16|512")
        assertEquals(0, w.kAJ, "S!=0 → aJ machine skipped")
        assertEquals(0, w.kAM)
    }

    @Test fun `ax42 kind0 fires when the bound entity expires`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 30)
        e.setAnim(0)                                          // arm: S==0
        // bound entity uid 77, dead (aB<=0 → P()==true)
        val dead = Entity(6, null); dead.aw = 77; dead.aB = 0
        w.npcs.add(dead)
        w.sfxLog.clear()
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(1, w.kAJ); assertEquals(-40, w.kAK); assertEquals(30, w.kAL)
        assertNull(e.s, "s=null after L27 fire")
        assertTrue(9 in w.sfxLog, "k.A(9) on fire")
    }

    @Test fun `ax42 kind0 waits while the bound entity lives`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 30)
        e.setAnim(0)
        val alive = Entity(6, null); alive.aw = 77; alive.aB = 10; alive.P = 32
        w.npcs.add(alive)
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(0, w.kAJ, "s.P&32 set → no fire")
        assertSame(alive, e.s, "s stays bound")
    }

    @Test fun `ax42 kind1 fires on bind even while s lives`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 1, 77, 45)
        e.setAnim(0)
        val alive = Entity(6, null); alive.aw = 77; alive.aB = 10; alive.P = 0
        w.npcs.add(alive)
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(1, w.kAJ, "Z0==1 && s.P&32==0 → L27 fire")
        assertEquals(45, w.kAL)
    }

    @Test fun `ax42 aJ2 expiry fails the mission`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak + 9000, p.al + 9000, 0, 77, 0)   // aL=0 → expires immediately
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 0; w.kAM = 0; w.kBw = 0; w.kBx = 0
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(-1, w.kBw, "bw=-1")
        assertEquals(58, w.kBx, "aj!=7 → bx=58")
        assertEquals(-1, w.kAL); assertEquals(0, w.kAM)
        assertEquals(2, w.kAJ, "this arm doesn't write aJ")
    }

    @Test fun `ax42 aJ2 overlap while ticking collects`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 10)                // aL=10s
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 10; w.kAM = 0
        p.refreshBoxes(); e.refreshBoxes()
        w.npcFsm.tickAx42(e, w, p)
        assertTrue(e in w.pendingRemove, "player∩W → k.c(this)")
        assertEquals(3, w.kAJ)
        assertEquals(0, w.kBw, "no fail write")
    }

    @Test fun `ax42 kind2 expiry binds script then aa-steps it`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        // uid absent from k.eH → kSIndex = -1 → bindScript(-1) leaves
        // ca=-1 → claimActive false (the aJ==3 remove+reset tail).
        w.kEh = intArrayOf(999)
        val e = ax42At(w, p.ak + 9000, p.al, 2, 1234, 0)
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 0; w.kAM = 0; w.kBw = 0
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(3, w.kAJ)
        assertEquals(-1, e.ca, "h(k.s(Z[1])) → bindScript(-1)")
        w.npcFsm.tickAx42(e, w, p)
        assertTrue(e in w.pendingRemove, "!claimActive → k.c(this)")
        assertEquals(-1, w.kAL); assertEquals(0, w.kAM); assertEquals(2, w.kBw)
    }
}
