        assertEquals(1, w.bO); assertEquals(3, w.bN0); assertEquals(42, w.dialogLine)
        // case-21 u==9 semantics (k.java:944-1017): a press edge while
        // typing only forces `bT=-1` (reveal); u==9 has NO page-advance
