        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax9At(w, p.ak - 4, p.al, 0)
        p.ag = -1; p.refreshBoxes()
        e.W[0] = p.ak - 40; e.W[1] = p.al - 40
        e.W[2] = p.ak + 40; e.W[3] = p.al + 40
        e.pushContact(w)
