        assertEquals(19, w.jC)                     // fF==19 → fO=3 + l(19)
        assertEquals(3, w.kFo)
        assertEquals(0, w.kFF)
    }

    @Test fun `af footer arms right pill to back`() {
        val w = world()
        w.stateL(30)
        w.tick(emptyList())
        assertEquals(w.d0(79) to w.d0(17), w.menuFooter())
