        assertEquals(-1, w.iBF); assertEquals(-1, w.iBG)
        assertEquals(4, p.S, "player i(4) climb enter")
        assertTrue(w.iBi, "i.bi climb-active")
        assertEquals(199, p.az)
        assertNull(p.ae, "hand released after the press")
    }

