    @Test fun `S10 bF outside the window aborts L46b`() {
        val w = S141World(); w.iBB = true; w.iBF = 95   // > Z[3]=90
        val z = climbZone()
        val p = mk(200, 130); p.W[1] = 70        // outside band, overlapping
