    @Test fun `S14 ax69 Z0=1 pins player ak to target center L1704`() {
        val w = S148World()
        val t = Entity(69, null); t.Z[0] = 1
        t.W[0] = 190; t.W[2] = 210                      // center 200
        t.W[1] = 110; t.W[3] = 130                      // inside zone
