    @Test fun `S23 publishes alive flag onto linked ax11 L1889`() {
        val w = S148World()
        val t = Entity(11, null); t.aw = 42; t.aB = 100
        t.W[0] = 190; t.W[2] = 210; t.W[1] = 100; t.W[3] = 140
        w.npcs += t
