        // dead target (aB<=0 → P() true) → cq = false
        t.aB = 0
        NpcFsm(w).tickTrigger(z, w, mk(0, 0), Pad())
        assertFalse(t.cq)
    }

    @Test fun `S28 enter sets aA8 + z0, exit clears L1aa7`() {
