    }

    @Test fun `S45 overlap hurts when bh3 else fails L1a79`() {
        val w = S148World(); w.bh = 3
        val p = mk(200, 120)
        NpcFsm(w).tickTrigger(zone(45), w, p, Pad())
        assertEquals(34, p.S)
